    uint32_t div = p->v[P_DLY_TIME] % NDDIV, samples;
    d = p->v[P_CHO_RATE]; PKV(16) = (uint32_t)(10 + ((d * d * 590) >> 14)) * 974u; /* 0.1 .. 5.9 Hz */
    PKV(19) = p->v[P_CHO_DEPTH] * 67; /* x the triangle's +-2048 = Q16 samples: up to +-6 ms */
    PKV(20) = p->v[P_CHO_MIX];
    PKV(21) = (p->v[P_DLY_MIX] * 180) >> 7; /* wet up to 0.7 of the dry (Q8): the sum stays in range */
    PKV(22) = (p->v[P_REV_MIX] * 180) >> 7;
