static void note_event_p(uint32_t part, uint32_t on, uint32_t note, uint32_t vel)
{
    if (PKV(71) - PKV(72) >= 64u) return; /* a flood: drop (the ISR drains 64 per block) */
    PKV(70)[PKV(71) % 64u].part = (uint8_t)part;
    PKV(70)[PKV(71) % 64u].type = (uint8_t)on;
    PKV(70)[PKV(71) % 64u].note = (uint8_t)note;
    PKV(70)[PKV(71) % 64u].vel = (uint8_t)vel;
    __asm__ volatile("" ::: "memory");
    PKV(71)++;
}
static void note_event(uint32_t on, uint32_t note, uint32_t vel) { note_event_p(0, on, note, vel); }
