    g->gain_q12 = (d * d) >> 2; /* (x CC 7 at the output: as VOLUME x CC 7 squared was) */
    g->pw1_base = ((uint32_t)pv[P_O1_PW] << 25) + (1u << 24);
    g->pw2_base = ((uint32_t)pv[P_O2_PW] << 25) + (1u << 24);
    g->w1 = pv[P_O1_WAVE];
    g->w2 = pv[P_O2_WAVE];
    g->ftype = pv[P_FTYPE];
