        + ((lfo * g->lfo_fd * 97) >> 15) + ((lfo * g->wheel_q * 48) >> 15) + ((VINT_CUT8[card % 8u] * vint) >> 7)
        + ((v->drift * vint) >> 7); /* the vintage walk on the cutoff too: ~1/4 semitone at the default */
